import {mountExperiment} from '../model-kit/session.js';
import {attachCardDrag} from '../shared/drag.js';
import {definition} from '../../../embed/definitions/lab-alignment.js';
import {create,project,replayPolicy,describe,SCENARIOS,FIELDS,ACTIONS,PRINCIPLES,DISTURBANCES,ORDERS,e} from './model.js';
const options=(values,current)=>Object.entries(values).map(([value,label])=>`<option value="${e(value)}" ${value===current?'selected':''}>${e(label)}</option>`).join('');
const num=(id,label,value,max)=>`<label for="${id}">${e(label)}<input id="${id}" data-number="${id}" type="number" min="0" max="${max}" step="1" value="${value}"></label>`;
function render(s,{pinned}){const r=project(s),p=pinned&&replayPolicy(s,pinned);return `
  <div class="alignment-intro"><label for="scenario">Situation<select id="scenario">${options(Object.fromEntries(Object.entries(SCENARIOS).map(([k,v])=>[k,v.name])),s.scenario)}</select></label><p>${e(r.scenario.description)}</p></div>
  <section class="disturbance-stage" aria-labelledby="disturbance-title"><p class="eyebrow">1 / DISTURB THE AGREEMENT</p><h2 id="disturbance-title">Everyone chose the same plan. What changes it?</h2><div class="disturbances">${Object.entries(DISTURBANCES).map(([id,label])=>`<button type="button" id="event-${id}" data-event="${id}" aria-pressed="${s.event===id}">${id==='none'?'○':'↳'} ${label}</button>`).join('')}</div><div class="event-reveal"><p>${r.event?e(r.event.detail):s.event==='none'?'No new evidence is introduced. The proposals follow the current starting beliefs and rules.':`${e(DISTURBANCES[s.event])}. The proposals below still show the starting situation until you reveal the evidence.`}</p>${s.event!=='none'?`<button id="reveal" type="button">${s.revealed?'Return to before the disturbance':'Reveal responses'}</button>`:''}</div></section>
  <section class="response-stage" aria-labelledby="response-title"><p class="eyebrow">2 / FOLLOW THE REASONING</p><h2 id="response-title">One plan, three explanations</h2><p class="alignment-verdict">${e(r.disposition)}</p><div class="response-paths">${r.people.map((person,i)=>`<article class="response-path"><h3>${e(person.name)}</h3><dl class="person-evidence">${Object.keys(FIELDS).map(key=>`<dt>${FIELDS[key]}</dt><dd><strong>${person.evidence[key]}</strong><span>${person.sources[key]}</span></dd>`).join('')}</dl><ol class="decision-path">${person.trace.map(t=>`<li class="${t.triggered?'triggered':''}"><span>${FIELDS[t.field]} ${t.operator} ${t.threshold}?</span><strong>${t.reading} → ${t.triggered?'yes':'no'}</strong></li>`).join('')}</ol><p class="response-action">${ACTIONS[person.action]}</p><p class="rule-order">First true check wins. Order: ${ORDERS[person.rule.priority].join(' → ')}.</p>${p?`<p class="pinned-response">Pinned policy: <strong>${ACTIONS[p.people[i].action]}</strong></p>`:''}</article>`).join('')}</div>${p?`<p class="comparison-note">Pinned replay: ${e(p.disposition)} Both policies use the current scenario, starting beliefs and revealed disturbance. The pin retains rules, shared-evidence choices, shared limits and decision scope.</p>`:''}</section>
  <section class="evidence-stage" aria-labelledby="evidence-title"><p class="eyebrow">3 / CHANGE WHAT IS SHARED</p><h2 id="evidence-title">Which evidence reaches everyone?</h2><p>Move a reading between the two areas, or use its checkbox. Sharing replaces each person’s belief with the scenario reading; it does not change their rule.</p><div class="evidence-board">${[false,true].map(shared=>`<section class="evidence-lane" data-drop-id="${shared?'shared':'private'}"><h3>${shared?'Shared with everyone':'Held where it arrived'}</h3><p>${shared?'Everyone uses the same scenario reading.':'Each person keeps their starting belief unless they directly received the disturbance.'}</p><div>${Object.keys(FIELDS).filter(k=>s.shared[k]===shared).map(k=>`<article class="evidence-token" data-drag-id="${k}"><button data-drag-handle type="button" aria-label="Drag ${FIELDS[k]} between evidence areas">↕ ${FIELDS[k]}</button><p>Scenario reading: <strong>${r.actual[k]}</strong></p><label for="share-${k}"><input id="share-${k}" data-share="${k}" type="checkbox" ${shared?'checked':''}> Share with everyone</label></article>`).join('')||'<p class="empty-evidence">Move a reading here</p>'}</div></section>`).join('')}</div>
  <div class="shared-agreement"><label for="principle">Shared decision principle<select id="principle">${options(PRINCIPLES,s.principle)}</select></label><label for="scope">Decision boundary<select id="scope">${options({local:'Each lead can decide locally',joint:'Joint review when proposals differ'},s.scope)}</select></label></div><p>Local decisions ${r.scenario.joint?'affect one shared release in this situation. Different actions leave an unresolved conflict.':'belong to separate remits in this situation. Different actions can coexist.'} A joint boundary holds differing proposals for review; it does not manufacture consensus.</p>
  ${s.principle!=='individual'?`<div class="shared-limits"><p>The shared principle replaces individual check order and thresholds with these explicit limits.</p><div class="alignment-input-grid">${num('limits-demand','Test if demand is below (%)',s.limits.demand,100)}${num('limits-risk','Pause if safety issues exceed',s.limits.risk,20)}${num('limits-delay','Reduce scope if delay exceeds (days)',s.limits.delay,30)}</div></div>`:''}</section>
  <details id="individual-rules" class="alignment-detail"><summary>Edit the starting beliefs and individual rules</summary><p>These are fictional rules, not personality traits. Rules are tested in order; the first true condition determines the proposed action. Equality does not trigger a change. Starting beliefs remain stored when shared readings replace them.</p><div class="individual-rules">${r.scenario.people.map((name,i)=>`<section><h3>${e(name)}</h3><h4>Starting beliefs</h4>${Object.keys(FIELDS).map(k=>num(`beliefs-${i}-${k}`,FIELDS[k],s.beliefs[i][k],k==='demand'?100:k==='risk'?20:30)).join('')}<h4>Decision rule</h4><label for="rule-priority-${i}">Check order<select id="rule-priority-${i}" data-priority="${i}">${options(Object.fromEntries(Object.entries(PRINCIPLES).filter(([k])=>k!=='individual')),s.rules[i].priority)}</select></label>${num(`rules-${i}-demand`,'Test if demand is below (%)',s.rules[i].demand,100)}${num(`rules-${i}-risk`,'Pause if safety issues exceed',s.rules[i].risk,20)}${num(`rules-${i}-delay`,'Reduce scope if delay exceeds (days)',s.rules[i].delay,30)}</section>`).join('')}</div></details>
  <details id="mechanism-notes" class="alignment-detail"><summary>Mechanism, limits and inspiration</summary><p>The starting plan is a coincidence of explicit rules and readings. A disturbance sends new values to the named recipient. A shared evidence choice distributes that scenario reading to everyone. A shared principle changes check order and thresholds; a joint decision boundary changes what happens to different proposals.</p><p>These are deterministic proposed responses, not predictions of people or the results of their actions. A scenario reading is treated as accepted evidence; the model does not simulate its accuracy, persuasion, trust, negotiation or execution. “Demand” is an illustrative survey reading; “safety issues” are an unweighted count. Change the thresholds to challenge the conclusions.</p><p>There is no score for agreement. Try the independent pilots where different actions can coexist, or the routine rehearsal where different rules keep producing the same action.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-215-shallow-vs-deep-alignment">Shallow vs. Deep Alignment</a> and <a href="https://cutlefish.substack.com/p/tbm-2453-mapping-beliefs-and-agreeing">Mapping Beliefs</a>. The playable if/then mechanism is an original illustration.</p></details>`;}
function bind({root,state:s,change}){const update=(apply,message)=>{const next=structuredClone(s);apply(next);change(next,message);};root.querySelector('#scenario').addEventListener('change',event=>change(create(event.target.value),'Loaded another fictional situation.'));root.querySelectorAll('[data-event]').forEach(button=>button.addEventListener('click',()=>update(next=>{next.event=button.dataset.event;next.revealed=false;},'Disturbance selected. Reveal to inspect new responses.')));root.querySelector('#reveal')?.addEventListener('click',()=>update(next=>next.revealed=!next.revealed,s.revealed?'Returned to starting information.':'New evidence revealed.'));root.querySelectorAll('[data-share]').forEach(input=>input.addEventListener('change',()=>update(next=>next.shared[input.dataset.share]=input.checked,'Changed who receives this reading.')));for(const key of ['principle','scope'])root.querySelector('#'+key).addEventListener('change',event=>update(next=>next[key]=event.target.value,'Decision agreement changed.'));root.querySelectorAll('[data-priority]').forEach(input=>input.addEventListener('change',()=>update(next=>next.rules[Number(input.dataset.priority)].priority=input.value,'Individual check order changed.')));root.querySelectorAll('[data-number]').forEach(input=>input.addEventListener('change',()=>{if(!input.checkValidity())return input.reportValidity();update(next=>{const [kind,index,key]=input.dataset.number.split('-');if(kind==='limits')next.limits[index]=Number(input.value);else next[kind][Number(index)][key]=Number(input.value);},'Belief or threshold changed.');}));return attachCardDrag({root,onDrop:({itemId,dropId})=>update(next=>next.shared[itemId]=dropId==='shared','Evidence audience changed.')});}
await mountExperiment({route:'alignment',definition,render,bind,describe});
